# Runtime v2 · B9 Semantics, accessibility và kiểm thử UI (viết lại; giữ mục v1 'sem')
# Nguồn: "Semantics in Compose", "Merging and clearing", "Test your Compose layout", "Testing APIs", "Synchronize your tests"
# (developer.android.com, đọc 2026-11-23); Kunneth Ch.10 (createComposeRule, finder/action/assertion, testTag, custom semantics property,
# Layout Inspector, InspectorInfo); Jetpack Compose by Tutorials Ch.14–15 (vùng chạm 48dp, contentDescription, click label, clearAndSetSemantics,
# custom actions, heading, stateDescription).

SEC_ORDER = {'b9': ['hook', 'tree', 'merge', 'sem', 'clear', 'a11y', 'test', 'sync', 'debug', 'bugs', 'exercises', 'recall']}

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    # ---------------- sim runtime.focus ----------------
    m = lambda k, vi, en=None: a('m.focus.' + k, vi, en)
    m('title', 'Một hàng bài viết qua cây semantics: TalkBack dừng mấy lần?', 'An article row through the semantics tree: how many TalkBack stops?')
    m('overview', 'Hàng bài viết theo ví dụ của trang Merging and clearing: ảnh nhỏ (có contentDescription), tiêu đề, dòng thông tin, nút đánh dấu. Ba cách viết: Row thường; Row có `clickable` (gộp con cháu); Row có `clickable` cộng `customActions`, còn nút đánh dấu bị `clearAndSetSemantics { }`. Xem cây semantics, số điểm dừng của TalkBack và node mà test tìm thấy.', 'The Android docs say: a thumbnail (with a contentDescription), a title, a metadata line and a bookmark button. Three ways to write it: a plain Row; a Row with `clickable` (merging its descendants); a Row with `clickable` plus `customActions`, with the bookmark button under `clearAndSetSemantics { }`. Watch the semantics tree, the number of TalkBack stops and the node a test finds.')
    m('wrapup', 'Cây semantics song song với cây UI, chỉ chứa ý nghĩa (text, contentDescription, role, action), không chứa cách vẽ. Gộp (`mergeDescendants`, có sẵn trong `clickable`, `toggleable`, `Button`) biến cả nhóm thành một điểm dừng; con nào tự gộp (nút, clickable) thì đứng riêng. `clearAndSetSemantics` xóa semantics của chính nó và con cháu cho MỌI người dùng cây (trợ năng, autofill, test), nên dùng tiết kiệm. Dịch vụ trợ năng đọc cây unmerged và tự gộp; test mặc định dùng cây merged.', 'The semantics tree runs parallel to the UI tree and holds only meaning (text, contentDescription, role, actions), not drawing. Merging (`mergeDescendants`, built into `clickable`, `toggleable`, `Button`) turns a whole group into one stop; a child that merges itself (a button, a clickable) stays separate. `clearAndSetSemantics` erases the semantics of the node and its descendants for EVERY consumer of the tree (accessibility, autofill, tests), so use it sparingly. Accessibility services read the unmerged tree and merge it themselves; tests use the merged tree by default.')
    m('simp.1', 'Số điểm dừng của TalkBack là mô hình: tài liệu nói mỗi node của cây semantics là một phần tử nhận focus khi dùng dịch vụ trợ năng, nhưng hành vi thật còn phụ thuộc phiên bản TalkBack và thiết bị (Tutorials cũng lưu ý điều này).', 'The TalkBack stop counts are a model: the docs say each node of the semantics tree is a focusable element for accessibility services, but real behaviour also depends on the TalkBack version and device (Tutorials notes this too).')
    m('simp.2', 'Số node của cây unmerged đếm các composable có semantics trong ví dụ (ảnh, hai Text, IconButton, icon của nút, và Row khi Row có clickable); Column không đặt semantics nên không có node.', 'The unmerged node count covers the composables with semantics in the example (thumbnail, two Texts, the IconButton, the button\'s icon, and the Row when it is clickable); the Column sets no semantics, so it has no node.')
    m('ctl.hint', 'Chạy Row thường trước, rồi bản gộp, cuối cùng bản custom action.', 'Run the plain Row first, then the merged one, then the custom-action version.')
    m('ctl.which', 'Cách viết hàng', 'How the row is written')
    for k, vi, en in [('plain', 'Row thường', 'Plain Row'), ('merge', 'Row.clickable (gộp)', 'Row.clickable (merging)'), ('clear', 'clickable + customActions, nút bị clear', 'clickable + customActions, button cleared')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'Cây UI, cây semantics và hai bên dùng nó', 'The UI tree, the semantics tree and its two consumers')
    m('diagramDesc', 'Cây UI sinh cây semantics; TalkBack và framework kiểm thử cùng đọc cây đó', 'The UI tree produces the semantics tree; TalkBack and the testing framework both read it')
    for k, vi, en in [('ui', 'Cây UI (ArticleRow)', 'UI tree (ArticleRow)'), ('sem', 'Cây semantics', 'Semantics tree'), ('a11y', 'TalkBack (cây unmerged)', 'TalkBack (unmerged tree)'), ('test', 'Test (cây merged)', 'Test (merged tree)')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('nodes', 'Node semantics (unmerged)', 'Semantics nodes (unmerged)'), ('stops', 'Điểm dừng TalkBack', 'TalkBack stops'), ('actions', 'Custom action', 'Custom actions')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('nodes', 'Số node unmerged', 'Unmerged nodes'), ('stops', 'Điểm dừng', 'Stops'), ('found', 'onNodeWithText("Compose phases") tìm thấy', 'onNodeWithText("Compose phases") finds')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.plain', 'Row thường', 'A plain Row', 'Không có modifier nào gộp: mỗi phần tử có semantics là một node riêng.', 'No merging modifier: every element with semantics is its own node.'),
        ('intro.merge', 'Row có clickable', 'A Row with clickable', 'Cả hàng mở bài viết khi bấm. `clickable` mang sẵn một semantics modifier có gộp con cháu.', 'The whole row opens the article when tapped. `clickable` brings a semantics modifier that merges descendants.'),
        ('intro.clear', 'Row clickable cộng customActions', 'A clickable Row plus customActions', 'Như Tutorials và trang Merging: nút đánh dấu bị `clearAndSetSemantics { }`, còn hành động của nó được chuyển lên Row thành custom action.', 'As in the Android docs on merging: the bookmark button is under `clearAndSetSemantics { }`, and its action moves up to the Row as a custom action.'),
        ('tree.plain', 'Cây unmerged: 5 node', 'The unmerged tree: 5 nodes', 'Ảnh (contentDescription), hai Text, IconButton (role Button, onClick) và icon bên trong nó.', 'The thumbnail (contentDescription), two Texts, the IconButton (role Button, onClick) and the icon inside it.'),
        ('tree.merge', 'Cây unmerged: 6 node', 'The unmerged tree: 6 nodes', 'Thêm node của Row (có onClick và cờ gộp). Cây unmerged giữ nguyên mọi node; gộp là việc của người đọc cây.', 'Plus the Row\'s node (with onClick and the merge flag). The unmerged tree keeps every node; merging is up to whoever reads the tree.'),
        ('tree.clear', 'Cây unmerged: 4 node', 'The unmerged tree: 4 nodes', 'Nút đánh dấu và icon của nó biến mất khỏi cây: `clearAndSetSemantics { }` với lambda rỗng xóa semantics của chính nó và con cháu. Row có thêm custom action "Add to bookmarks".', 'The bookmark button and its icon vanish from the tree: `clearAndSetSemantics { }` with an empty lambda erases its own and its descendants\' semantics. The Row gains the "Add to bookmarks" custom action.'),
        ('rule.plain', 'Không có gì để gộp', 'Nothing to merge', 'Không node nào đặt `mergeDescendants` ngoài IconButton (gộp icon của chính nó).', 'No node sets `mergeDescendants` except the IconButton (merging its own icon).'),
        ('rule.merge', 'Gộp: ảnh và hai Text vào Row; nút đứng riêng', 'Merging: the thumbnail and two Texts into the Row; the button stays apart', 'Mỗi thuộc tính có luật gộp riêng; ví dụ contentDescription và text được gom thành danh sách. Nhưng cha không gộp được con đang TỰ gộp: IconButton là clickable nên không bị gộp vào Row.', 'Each property has its own merge policy; contentDescription and text, for example, are collected into lists. But a parent cannot merge children that merge THEMSELVES: the IconButton is clickable, so it is not merged into the Row.'),
        ('rule.clear', 'Gộp phần còn lại vào Row', 'Merging the rest into the Row', 'Ảnh và hai Text gộp vào Row như trên; nút đã bị xóa nên không còn gì đứng riêng.', 'The thumbnail and two Texts merge into the Row as before; the button has been erased, so nothing stands apart.'),
        ('walk.plain', 'TalkBack dừng {n} lần cho một hàng', 'TalkBack stops {n} times for one row', 'Người dùng phải vuốt qua ảnh, tiêu đề, dòng thông tin rồi nút cho MỖI bài viết. Tutorials gặp đúng vấn đề này với danh sách bài đăng.', 'The user must swipe through the thumbnail, the title, the metadata and the button for EVERY article. Tutorials hits exactly this with a list of posts.'),
        ('walk.merge', 'TalkBack dừng {n} lần', 'TalkBack stops {n} times', 'Một lần cho cả hàng (đọc ảnh, tiêu đề, thông tin cùng lúc), một lần cho nút đánh dấu.', 'Once for the whole row (reading the thumbnail, title and metadata together), once for the bookmark button.'),
        ('walk.clear', 'TalkBack dừng {n} lần', 'TalkBack stops {n} time', 'Một điểm dừng cho cả hàng; "Add to bookmarks" nằm trong menu hành động của TalkBack.', 'One stop for the whole row; "Add to bookmarks" lives in TalkBack\'s actions menu.'),
        ('find.plain', 'Test tìm thấy chính Text', 'The test finds the Text itself', '`onNodeWithText("Compose phases")` dùng cây merged mặc định; không có gộp nên node là Text.', '`onNodeWithText("Compose phases")` uses the merged tree by default; nothing merges, so the node is the Text.'),
        ('find.merge', 'Test tìm thấy node Row đã gộp', 'The test finds the merged Row node', 'Trong cây merged, text của hai Text nằm trong node Row, nên finder trả về Row. Muốn đúng node Text thì truyền `useUnmergedTree = true`.', 'In the merged tree, the two Texts\' text lives in the Row node, so the finder returns the Row. To get the Text node itself, pass `useUnmergedTree = true`.'),
        ('find.clear', 'Test tìm thấy node Row đã gộp', 'The test finds the merged Row node', 'Như bản gộp. Lưu ý: nút đánh dấu đã bị xóa khỏi cây nên test cũng không tìm được nó nữa; hãy test qua custom action.', 'As in the merged version. Note: the bookmark button is gone from the tree, so tests cannot find it either; test it through the custom action.'),
        ('end.plain', 'Kết thúc: đúng nhưng mệt cho người dùng TalkBack', 'The end: correct, but tiring for TalkBack users', 'Mọi thông tin đều có, nhưng chia quá nhỏ.', 'All the information is there, but split too finely.'),
        ('end.merge', 'Kết thúc: một hàng, một nút', 'The end: one row, one button', 'Độ chia vừa phải cho phần lớn danh sách.', 'A sensible granularity for most lists.'),
        ('end.clear', 'Kết thúc: một điểm dừng, một custom action', 'The end: one stop, one custom action', 'Nhanh nhất để lướt danh sách, đổi lại mọi thứ phải được khai báo tay.', 'The fastest way to skim a list, at the price of declaring everything by hand.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('rule.plain', 'Tài liệu: composable không đặt thuộc tính semantics nào thì không có mặt trong cây semantics. [[src:cp-semantics]]', 'The docs: a composable with no semantics properties set is not part of the semantics tree. [[src:cp-semantics]]'),
        ('rule.merge', 'Tài liệu Android nói: cha không gộp được con khi con cũng đang gộp, do `mergeDescendants = true` hoặc vì là nút, clickable. [[src:cp-merging]]', 'The Android docs say: a parent cannot merge its children when the children are also merging, through `mergeDescendants = true` or by being buttons or clickables. [[src:cp-merging]]'),
        ('rule.clear', 'Tài liệu Android nói: thứ tự modifier quan trọng, `clearAndSetSemantics` xóa mọi semantics đứng SAU nó, bất kể luật gộp. [[src:cp-merging]]', 'The Android docs say: modifier order matters; `clearAndSetSemantics` clears all semantics after where it is applied, regardless of merging. [[src:cp-merging]]'),
        ('find', 'Finder và matcher mặc định dùng cây merged; `useUnmergedTree = true` đổi sang cây unmerged. [[src:cp-semantics]] [[src:cp-testing-apis]]', 'Finders and matchers use the merged tree by default; `useUnmergedTree = true` switches to the unmerged tree. [[src:cp-semantics]] [[src:cp-testing-apis]]'),
        ('end.plain', 'Tutorials gom hành động của bài đăng thành custom action để lướt nhanh hơn. [[src:book-compose-tut]]', 'Tutorials groups a post\'s actions into custom actions for faster skimming. [[src:book-compose-tut]]'),
        ('end.merge', '`clickable`, `toggleable` và `ListItem` tự gộp con cháu. [[src:cp-semantics]]', '`clickable`, `toggleable` and `ListItem` merge their descendants automatically. [[src:cp-semantics]]'),
        ('end.clear', 'Tài liệu: dịch vụ không nhận thông tin gì khi API này được đặt, nên dùng tiết kiệm; semantics còn có thể được AI agent dùng để hiểu màn hình. [[src:cp-merging]]', 'The docs: services receive no information when this API is set, so use it sparingly; semantics may also be used by AI agents to understand the screen. [[src:cp-merging]]')]:
        m('co.' + k, vi, en)
    a('cap.focus', 'Từ trái sang phải: cây UI của ArticleRow sinh cây semantics; bên phải trên là TalkBack (đọc cây unmerged và tự gộp), bên phải dưới là framework kiểm thử (mặc định đọc cây merged). Chỉ số đếm node unmerged, điểm dừng TalkBack và custom action.', 'Left to right: ArticleRow\'s UI tree produces the semantics tree; top right is TalkBack (reading the unmerged tree and merging itself), bottom right is the testing framework (reading the merged tree by default). The metrics count unmerged nodes, TalkBack stops and custom actions.')

    # ---------------- chương B9 ----------------
    C = 'b9'
    a(C + '.sim.runtime.focus', 'Gộp, xóa và điểm dừng', 'Merging, clearing and stops')
    a(C + '.sim.runtime.semantics', 'Ai đọc cây nào', 'Who reads which tree')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', '`Button(onClick = {}) { Icon(Icons.Filled.Favorite, contentDescription = null); Text("Like") }`. Trong test, `onNodeWithText("Like")` trả về node nào: Text hay Button? Và `.performClick()` trên đó có chạy `onClick` không?', '`Button(onClick = {}) { Icon(Icons.Filled.Favorite, contentDescription = null); Text("Like") }`. In a test, which node does `onNodeWithText("Like")` return: the Text or the Button? And does `.performClick()` on it run `onClick`?')
    B(C, S, 1, 'ans', 'Node của Button. Button gộp con cháu (nó dùng `clickable`), nên trong cây merged mà test dùng mặc định, chữ "Like" nằm trong node của Button, node đó có action click. Vì vậy `performClick()` chạy `onClick`. Đây đúng là ví dụ của trang Semantics. [[src:cp-semantics]]', 'The Button\'s node. The Button merges its descendants (it uses `clickable`), so in the merged tree that tests use by default, "Like" lives in the Button\'s node, which has the click action. So `performClick()` runs `onClick`. This is exactly the Semantics page\'s example. [[src:cp-semantics]]')

    S = 'tree'
    a(C + '.sec.%s.title' % S, 'Cây semantics: ý nghĩa, không phải hình vẽ', 'The semantics tree: meaning, not drawing')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Semantics là "thông tin về ý nghĩa và vai trò của một component": một icon máy ảnh có thể mang nghĩa "Chụp ảnh". Composition là cây composable; song song với nó là cây semantics, mô tả UI cho dịch vụ trợ năng và framework kiểm thử. Cây này không biết cách VẼ, chỉ biết Ý NGHĨA; mỗi node là một phần tử nhận focus khi dùng dịch vụ trợ năng. Composable không đặt thuộc tính semantics nào thì không có node. [[src:cp-semantics]]', 'Semantics is "information about the meaning and role of a component": a camera icon may mean "Take a photo". The Composition is a tree of composables; in parallel there is the semantics tree, describing the UI for accessibility services and the testing framework. It does not know how to DRAW, only the MEANING; each node is a focusable element when using accessibility services. A composable with no semantics properties set has no node. [[src:cp-semantics]]')
    B(C, S, 2, 'p', 'Component của foundation và Material tự điền semantics: `Text` mang `text`, `Icon` mang `contentDescription` nếu bạn đặt, `Switch` mang Role, StateDescription, ToggleableState và OnClick. Composable tự vẽ ở mức thấp (Layout, Canvas) thì phải tự khai báo; ví dụ của tài liệu là một lịch tự vẽ mà TalkBack chỉ đọc được "Calendar", người dùng không biết ngày nào đang chọn. Kunneth nhấn mạnh cùng ý từ phía test: Compose không có tham chiếu tới phần tử UI như View, nên test tìm phần tử qua cây semantics; làm app dễ tiếp cận cũng làm test dễ viết. [[src:cp-semantics]] [[src:book-kunneth]]', 'Foundation and Material components fill in semantics themselves: `Text` carries `text`, `Icon` carries `contentDescription` if you set it, `Switch` carries Role, StateDescription, ToggleableState and OnClick. Low-level custom composables (Layout, Canvas) must declare their own; the docs\' example is a hand-drawn calendar that TalkBack can only read as "Calendar", so the user cannot tell which day is selected. Kunneth makes the same point from the testing side: Compose has no references to UI elements as Views do, so tests find elements through the semantics tree; making the app accessible also makes tests easier to write. [[src:cp-semantics]] [[src:book-kunneth]]')

    S = 'merge'
    a(C + '.sec.%s.title' % S, 'Gộp: một nhóm, một điểm dừng', 'Merging: one group, one stop')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`Modifier.semantics(mergeDescendants = true) {}` gộp thuộc tính của con cháu vào node này. `clickable` và `toggleable` tự làm vậy, nên `Button` và `ListItem` gộp sẵn. Mỗi thuộc tính có luật gộp riêng (`mergePolicy`): ví dụ `ContentDescription` gom mọi giá trị của con cháu thành một danh sách; có thuộc tính lấy giá trị cha hoặc con, có thuộc tính không cho gộp. [[src:cp-semantics]] [[src:cp-merging]]', '`Modifier.semantics(mergeDescendants = true) {}` merges descendants\' properties into this node. `clickable` and `toggleable` do so themselves, so `Button` and `ListItem` merge out of the box. Each property has its own merge policy (`mergePolicy`): `ContentDescription`, for example, collects every descendant value into a list; some properties take the parent\'s or child\'s value, some refuse to merge. [[src:cp-semantics]] [[src:cp-merging]]')
    B(C, S, 2, 'p', 'Luật quan trọng nhất của trang Merging: "A parent cannot merge its children when the children are also merging". Một nút hay một clickable nằm trong hàng clickable vẫn đứng riêng: nhờ vậy người dùng TalkBack vẫn bấm được nút đánh dấu bên trong hàng bài viết. Mô phỏng ngay dưới cho thấy số điểm dừng ở ba cách viết. [[src:cp-merging]]', 'The Merging page\'s most important rule: "A parent cannot merge its children when the children are also merging". A button or clickable inside a clickable row still stands apart: that is how TalkBack users can still press the bookmark button inside an article row. The simulation just below shows the number of stops for three ways of writing the row. [[src:cp-merging]]')

    S = 'clear'
    a(C + '.sec.%s.title' % S, 'Xóa, ghi đè và ẩn semantics', 'Clearing, overriding and hiding semantics')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`clearAndSetSemantics { }` với lambda rỗng xóa semantics của chính node và con cháu cho MỌI bên dùng (trợ năng, autofill, test); với nội dung trong lambda thì semantics mới thay toàn bộ semantics cũ. Tài liệu dặn dùng tiết kiệm, và nhớ thứ tự modifier: nó xóa mọi semantics đứng sau nó. Ví dụ của tài liệu: một Row `toggleable` tự đặt `stateDescription`, `toggleableState`, `role = Role.Switch` để đọc như một công tắc thật. Nếu chỉ muốn ẩn khỏi trợ năng mà vẫn giữ cho test, dùng `Modifier.semantics { hideFromAccessibility() }` (ví dụ watermark, dấu chấm trang trí). [[src:cp-merging]]', '`clearAndSetSemantics { }` with an empty lambda erases the semantics of the node and its descendants for EVERY consumer (accessibility, autofill, tests); with content in the lambda, the new semantics replace all the old ones. The docs ask for sparing use, and remember modifier order: it clears everything after it. The docs\' example: a `toggleable` Row that sets `stateDescription`, `toggleableState` and `role = Role.Switch` itself so it reads like a real switch. If you only want to hide something from accessibility but keep it for tests, use `Modifier.semantics { hideFromAccessibility() }` (a watermark, a decorative dot). [[src:cp-merging]]')
    B(C, S, 2, 'kt', 'Row(\n    modifier = Modifier\n        .toggleable(value = checked.value, onValueChange = { checked.value = it })\n        .clearAndSetSemantics {\n            stateDescription = if (checked.value) "Favorited" else "Not favorited"\n            toggleableState = ToggleableState(checked.value)\n            role = Role.Switch\n        },\n) {\n    Icon(imageVector = Icons.Default.Favorite, contentDescription = null)   // không cần nữa\n    Text("Favorite?")\n}', 'Row(\n    modifier = Modifier\n        .toggleable(value = checked.value, onValueChange = { checked.value = it })\n        .clearAndSetSemantics {\n            stateDescription = if (checked.value) "Favorited" else "Not favorited"\n            toggleableState = ToggleableState(checked.value)\n            role = Role.Switch\n        },\n) {\n    Icon(imageVector = Icons.Default.Favorite, contentDescription = null)   // no longer needed\n    Text("Favorite?")\n}')

    S = 'a11y'
    a(C + '.sec.%s.title' % S, 'Accessibility thực hành (Tutorials)', 'Practical accessibility (Tutorials)')
    a(C + '.sec.%s.badge' % S, 'guideline')
    B(C, S, 1, 'p', 'Tutorials sửa app JetReddit bằng TalkBack, từng bước: (1) vùng chạm ít nhất 48dp: icon 24dp được thêm padding, hoặc thay bằng `IconButton`; (2) `contentDescription` có nghĩa cho icon tương tác ("Navigate to chat"), `null` cho hình trang trí; (3) nhãn hành động: `Modifier.semantics { onClick(label = "open chat", action = null) }` hoặc `clickable(onClickLabel = …)`, để TalkBack đọc "Double tap to open chat" thay vì "to activate"; (4) gom hành động của bài đăng thành custom action sau khi `clearAndSetSemantics { }` các nút con; (5) `heading()` để nhảy giữa các tiêu đề; (6) đưa toggle từ Switch lên cả hàng; (7) `stateDescription` cho trạng thái. Lưu ý TalkBack có thể khác nhau theo thiết bị và phiên bản. [[src:book-compose-tut]]', 'Tutorials fixes the JetReddit app with TalkBack, step by step: (1) touch targets of at least 48dp: a 24dp icon gets padding or is replaced with an `IconButton`; (2) meaningful `contentDescription` for interactive icons ("Navigate to chat"), `null` for decoration; (3) action labels: `Modifier.semantics { onClick(label = "open chat", action = null) }` or `clickable(onClickLabel = …)`, so TalkBack says "Double tap to open chat" instead of "to activate"; (4) grouping a post\'s actions into custom actions after `clearAndSetSemantics { }` on the child buttons; (5) `heading()` to jump between headings; (6) lifting toggle behaviour from a Switch to the whole row; (7) `stateDescription` for states. Note that TalkBack may differ across devices and versions. [[src:book-compose-tut]]')
    B(C, S, 2, 'p', 'Trang Semantics còn liệt kê các thuộc tính khác: `liveRegion` (báo thay đổi nội dung), `paneTitle`, `error(...)`, `progressBarRangeInfo`, `collectionInfo`/`collectionItemInfo`. Phần thiết kế (WCAG, độ tương phản, thiết kế bao hàm) ở cầu nối X6 và chương E10. [[src:cp-semantics]]', 'The Semantics page lists more properties: `liveRegion` (announcing content changes), `paneTitle`, `error(...)`, `progressBarRangeInfo`, `collectionInfo`/`collectionItemInfo`. The design side (WCAG, contrast, inclusive design) is in bridge X6 and chapter E10. [[src:cp-semantics]]')

    S = 'test'
    a(C + '.sec.%s.title' % S, 'Kiểm thử UI: finder, action, assertion', 'UI tests: finders, actions, assertions')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Kunneth: test UI là instrumented test (chạy trên emulator hay máy thật, thư mục `androidTest`). `createComposeRule()` trả về một `ComposeContentTestRule` (trên Android là `AndroidComposeTestRule<ComponentActivity>`, cần `ui-test-manifest`); `createAndroidComposeRule<YourActivity>()` khi cần chính Activity. `setContent` gọi đúng một lần mỗi test. Ba loại API: FINDER (`onNode`, `onAllNodes`, `onNodeWithText`, `onNodeWithContentDescription`) trả về `SemanticsNodeInteraction`; ACTION (`performClick()`, `performSemanticsAction`, …; không xâu chuỗi action bên trong một perform); ASSERTION (`assertExists`, `assertIsDisplayed`, `assert(hasText(...))`, `assertCountEquals`). [[src:book-kunneth]] [[src:cp-testing]] [[src:cp-testing-apis]]', 'Kunneth: UI tests are instrumented tests (run on an emulator or device, in the `androidTest` folder). `createComposeRule()` returns a `ComposeContentTestRule` (on Android an `AndroidComposeTestRule<ComponentActivity>`, which needs `ui-test-manifest`); use `createAndroidComposeRule<YourActivity>()` when you need the Activity itself. Call `setContent` exactly once per test. Three kinds of API: FINDERS (`onNode`, `onAllNodes`, `onNodeWithText`, `onNodeWithContentDescription`) return a `SemanticsNodeInteraction`; ACTIONS (`performClick()`, `performSemanticsAction`, …; actions cannot be chained inside one perform); ASSERTIONS (`assertExists`, `assertIsDisplayed`, `assert(hasText(...))`, `assertCountEquals`). [[src:book-kunneth]] [[src:cp-testing]] [[src:cp-testing-apis]]')
    B(C, S, 2, 'kt', '// Kunneth, SimpleButtonDemo: bấm đổi chữ A ↔ B\n@RunWith(AndroidJUnit4::class)\nclass SimpleInstrumentedTest {\n    @get:Rule\n    val rule = createComposeRule()\n\n    @Before\n    fun setup() { rule.setContent { SimpleButtonDemo() } }\n\n    @Test\n    fun testLetterAfterButtonClickIsB() {\n        rule.onNodeWithText("A")\n            .performClick()\n            .assert(hasText("B"))\n    }\n}\n\n// Không có chữ để tìm: gắn tag\nBox(Modifier.testTag("BoxButtonDemo"))\nrule.onNode(hasTestTag("BoxButtonDemo")).assertExists()', '// Kunneth, SimpleButtonDemo: a click toggles A ↔ B\n@RunWith(AndroidJUnit4::class)\nclass SimpleInstrumentedTest {\n    @get:Rule\n    val rule = createComposeRule()\n\n    @Before\n    fun setup() { rule.setContent { SimpleButtonDemo() } }\n\n    @Test\n    fun testLetterAfterButtonClickIsB() {\n        rule.onNodeWithText("A")\n            .performClick()\n            .assert(hasText("B"))\n    }\n}\n\n// Nothing to find by text: add a tag\nBox(Modifier.testTag("BoxButtonDemo"))\nrule.onNode(hasTestTag("BoxButtonDemo")).assertExists()')
    B(C, S, 3, 'p', 'Khi test cần thông tin không có trong cây (Kunneth muốn kiểm màu nền), có thể tạo thuộc tính semantics riêng: `val BackgroundColorKey = SemanticsPropertyKey<Color>("BackgroundColor")`, `var SemanticsPropertyReceiver.backgroundColor by BackgroundColorKey`, đặt trong `Modifier.semantics { backgroundColor = color }`, và tìm bằng `SemanticsMatcher.expectValue(BackgroundColorKey, COLOR1)`. Nhưng chính sách nhắc: cây semantics cũng phục vụ trợ năng, đừng làm bẩn nó bằng thông tin không liên quan; thường nên đổi cách test (kiểm state thay vì kiểm màu). In cây để xem: `onRoot(useUnmergedTree = true).printToLog("TAG")`. [[src:book-kunneth]] [[src:cp-semantics]]', 'When a test needs information missing from the tree (Kunneth wants to check a background colour), you can create a custom semantics property: `val BackgroundColorKey = SemanticsPropertyKey<Color>("BackgroundColor")`, `var SemanticsPropertyReceiver.backgroundColor by BackgroundColorKey`, set it in `Modifier.semantics { backgroundColor = color }`, and find it with `SemanticsMatcher.expectValue(BackgroundColorKey, COLOR1)`. But Thomas Künneth warns: the semantics tree also serves accessibility, so do not pollute it with irrelevant information; often it is better to change the test (check the state rather than the colour). To look at the tree: `onRoot(useUnmergedTree = true).printToLog("TAG")`. [[src:book-kunneth]] [[src:cp-semantics]]')

    S = 'sync'
    a(C + '.sec.%s.title' % S, 'Đồng bộ: đồng hồ ảo của test', 'Synchronisation: the test\'s virtual clock')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Trước mỗi action hay assertion, `ComposeTestRule` chờ cây UI rảnh. Thời gian là ảo: app được đẩy tới bằng một đồng hồ ảo nên test không chạy theo thời gian thật. Hệ quả: nếu test chỉ đổi state mà không gọi API có đồng bộ, sẽ không có recomposition nào và UI "như bị dừng" (tài liệu có ví dụ bộ đếm: một assert thường thấy giá trị cũ, `onNodeWithText("1").assertExists()` thì qua). Đây chính là frame clock của chương B5, do `MainTestClock` điều khiển: nó lái recomposition, animation, gesture, nhưng không điều khiển measure/draw của Android. [[src:cp-testing-sync]] [[src:cp-testing]]', 'Before every action or assertion, the `ComposeTestRule` waits for the UI tree to be idle. Time is virtual: the app is advanced by a virtual clock, so tests do not run in real time. The consequence: if a test only changes state without calling a synchronising API, no recomposition happens and the UI appears "paused" (the docs have a counter example: a plain assert sees the old value, while `onNodeWithText("1").assertExists()` passes). This is the frame clock of chapter B5, driven by `MainTestClock`: it drives recomposition, animations and gestures, but not Android\'s measure/draw. [[src:cp-testing-sync]] [[src:cp-testing]]')
    B(C, S, 2, 'kt', '// chụp giữa animation: tự điều khiển đồng hồ\ncomposeTestRule.mainClock.autoAdvance = false\ncomposeTestRule.onNodeWithText("Expand").performClick()\ncomposeTestRule.mainClock.advanceTimeBy(150)      // nhảy 150 ms ảo\ncomposeTestRule.mainClock.advanceTimeByFrame()     // thêm một frame\n\n// việc ngoài Compose (tải dữ liệu): đừng dùng CountDownLatch\ncomposeTestRule.waitUntil(timeoutMillis = 5_000) { repo.isLoaded }\ncomposeTestRule.waitUntilAtLeastOneExists(hasText("Done"), 5_000)', '// capture mid-animation: drive the clock yourself\ncomposeTestRule.mainClock.autoAdvance = false\ncomposeTestRule.onNodeWithText("Expand").performClick()\ncomposeTestRule.mainClock.advanceTimeBy(150)      // jump 150 virtual ms\ncomposeTestRule.mainClock.advanceTimeByFrame()     // one more frame\n\n// work outside Compose (loading data): do not use a CountDownLatch\ncomposeTestRule.waitUntil(timeoutMillis = 5_000) { repo.isLoaded }\ncomposeTestRule.waitUntilAtLeastOneExists(hasText("Done"), 5_000)')
    B(C, S, 3, 'p', 'Việc chạy nền không đồng bộ với Compose hay Espresso cần idling resource (`registerIdlingResource`). `waitForIdle()` phụ thuộc `autoAdvance`: bật thì đẩy đồng hồ tới khi Compose rảnh, tắt thì chỉ chờ idling resource. `mainClock.advanceTimeUntil { }` chỉ hợp với điều kiện trên state của Compose; điều kiện phụ thuộc việc bên ngoài dùng `waitUntil`. Tài liệu cảnh báo `CountDownLatch` bên ngoài có thể chạy sai vì đồng hồ test không được đẩy tới. [[src:cp-testing-sync]]', 'Background work not synchronised with Compose or Espresso needs an idling resource (`registerIdlingResource`). `waitForIdle()` depends on `autoAdvance`: on, it advances the clock until Compose is idle; off, it only waits for idling resources. `mainClock.advanceTimeUntil { }` only suits conditions on Compose state; conditions on outside work use `waitUntil`. The docs warn an external `CountDownLatch` can misbehave because the test clock is not advanced. [[src:cp-testing-sync]]')

    S = 'debug'
    a(C + '.sec.%s.title' % S, 'Debug: Layout Inspector và host Android', 'Debugging: the Layout Inspector and the Android host')
    a(C + '.sec.%s.badge' % S, 'android-impl')
    B(C, S, 1, 'p', 'Kunneth: trên Android mọi cây composable được bọc trong `ComposeView`, trực tiếp hay qua `ComponentActivity.setContent {}` (chương B1), nên debug không khác app View nhiều: đặt breakpoint trong composable như hàm Kotlin, và dùng Layout Inspector (cây bên trái, thuộc tính bên phải, xem 3D). Layout Inspector còn chọn được cây semantics merged hay unmerged, và đếm recomposition/skip (chương B8, PF). Thomas Künneth gợi ý modifier ghi log tạm (một `DrawModifier` in kích thước) nhưng nhắc chỉ thêm khi debug. Cách Thomas Künneth giải thích `InspectorInfo` dựa trên `composed {}`, cách mà chương MD cho biết nay không còn được khuyên dùng; ở commit ghim, `ModifierNodeElement` có `inspectableProperties()` cho cùng mục đích. [[src:book-kunneth]] [[src:cp-semantics]] [[src:ui-mne-src]]', 'Kunneth: on Android every composable tree is wrapped in a `ComposeView`, directly or through `ComponentActivity.setContent {}` (chapter B1), so debugging is not very different from View apps: set breakpoints in composables like any Kotlin function, and use the Layout Inspector (tree on the left, attributes on the right, a 3D view). The Layout Inspector can also choose the merged or unmerged semantics tree, and counts recompositions/skips (chapters B8, PF). Thomas Künneth suggests a temporary logging modifier (a `DrawModifier` printing the size) but says to add it only while debugging. Thomas Künneth\'s explanation of `InspectorInfo` builds on `composed {}`, which chapter MD shows is no longer recommended; at the pinned commit, `ModifierNodeElement` has `inspectableProperties()` for the same purpose. [[src:book-kunneth]] [[src:cp-semantics]] [[src:ui-mne-src]]')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', '`onNodeWithText("5 min read").assertHasClickAction()` thất bại dù cả hàng bấm được; với `onNodeWithText("Compose phases").performClick()` thì lại chạy.', '`onNodeWithText("5 min read").assertHasClickAction()` fails even though the whole row is clickable; yet `onNodeWithText("Compose phases").performClick()` works.')
    B(C, S, 1, 'cause', 'Đoán ngược: cả hai đều tìm thấy node Row đã gộp trong cây merged, node đó có click action. Nếu assertion thất bại thì test đang dùng `useUnmergedTree = true` (tìm ra Text, không có action), hoặc text nằm trong một con tự gộp khác.', 'Reverse it: both find the merged Row node in the merged tree, and that node has the click action. If the assertion fails, the test is using `useUnmergedTree = true` (finding the Text, which has no action), or the text sits in another self-merging child.')
    B(C, S, 1, 'fix', 'Hiểu cây nào đang được dùng: in `onRoot().printToLog()` và `onRoot(useUnmergedTree = true).printToLog()` rồi so. [[src:cp-semantics]] [[src:cp-testing-apis]]', 'Know which tree you are using: print `onRoot().printToLog()` and `onRoot(useUnmergedTree = true).printToLog()` and compare. [[src:cp-semantics]] [[src:cp-testing-apis]]')
    B(C, S, 2, 'bug', 'Sau khi thêm `clearAndSetSemantics { }` để TalkBack bớt dừng, test `onNodeWithContentDescription("Bookmark").performClick()` báo không tìm thấy node.', 'After adding `clearAndSetSemantics { }` to cut TalkBack stops, the test `onNodeWithContentDescription("Bookmark").performClick()` reports no such node.')
    B(C, S, 2, 'cause', 'Lambda rỗng xóa semantics cho MỌI bên dùng, kể cả test.', 'The empty lambda erases semantics for EVERY consumer, tests included.')
    B(C, S, 2, 'fix', 'Test qua custom action của hàng (`performSemanticsAction`/action tùy chỉnh), hoặc nếu chỉ cần ẩn với trợ năng thì dùng `hideFromAccessibility()`, vốn giữ semantics cho test. [[src:cp-merging]]', 'Test through the row\'s custom action, or if you only need to hide it from accessibility, use `hideFromAccessibility()`, which keeps semantics for tests. [[src:cp-merging]]')
    B(C, S, 3, 'bug', 'Test đổi state trực tiếp (`viewModel.count = 1`) rồi assert bằng một biến Kotlin ghi lại giá trị hiển thị, và thấy vẫn là 0.', 'A test changes state directly (`viewModel.count = 1`) then asserts on a Kotlin variable that records the displayed value, and sees 0.')
    B(C, S, 3, 'cause', 'Chưa có lời gọi đồng bộ nào: đồng hồ ảo chưa được đẩy, chưa có recomposition.', 'No synchronising call happened: the virtual clock has not advanced, so no recomposition yet.')
    B(C, S, 3, 'fix', 'Assert qua API của rule (`onNodeWithText("1").assertExists()`) hoặc gọi `waitForIdle()` trước. [[src:cp-testing-sync]]', 'Assert through the rule\'s API (`onNodeWithText("1").assertExists()`) or call `waitForIdle()` first. [[src:cp-testing-sync]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Sửa để TalkBack đọc "Navigate to chat. Button. Double tap to open chat" và vùng chạm đủ 48dp:', 'Fix it so TalkBack says "Navigate to chat. Button. Double tap to open chat" and the touch target is 48dp:')
    B(C, S, 1, 'exkt', 'Icon(\n    imageVector = Icons.Filled.Chat,\n    contentDescription = null,\n    modifier = Modifier.size(24.dp).clickable { openChat() }\n)')
    B(C, S, 1, 'hint', 'Ba thứ: contentDescription, onClickLabel, và kích thước vùng chạm (IconButton hoặc padding).', 'Three things: contentDescription, onClickLabel, and the touch area size (IconButton or padding).')
    B(C, S, 1, 'solkt', 'Icon(\n    imageVector = Icons.Filled.Chat,\n    contentDescription = "Navigate to chat",\n    modifier = Modifier\n        .clickable(onClickLabel = "open chat") { openChat() }\n        .padding(12.dp)          // 24 + 12 * 2 = 48dp vùng chạm\n        .size(24.dp)\n)')
    B(C, S, 1, 'sol', 'Theo Tutorials. `clickable` đứng trước `padding` để cả vùng 48dp nhận chạm (chương MD); dùng `IconButton` cũng được vì nó lo sẵn vùng chạm.', 'Following Tutorials. `clickable` comes before `padding` so the whole 48dp area receives taps (chapter MD); an `IconButton` also works because it handles the touch area.')
    B(C, S, 2, 'ex', 'Viết test cho bản "gộp" của ArticleRow: (a) bấm vào tiêu đề gọi `onOpen`; (b) nút đánh dấu tìm được bằng contentDescription và gọi `onBookmark`.', 'Write a test for the "merged" ArticleRow: (a) tapping the title calls `onOpen`; (b) the bookmark button can be found by contentDescription and calls `onBookmark`.')
    B(C, S, 2, 'solkt', '@get:Rule val rule = createComposeRule()\n\n@Test\nfun rowAndBookmark() {\n    var opened = false; var bookmarked = false\n    rule.setContent { ArticleRow(onOpen = { opened = true }, onBookmark = { bookmarked = true }) }\n    rule.onNodeWithText("Compose phases").performClick()          // node Row đã gộp\n    rule.onNodeWithContentDescription("Bookmark").performClick()   // nút tự gộp, đứng riêng\n    rule.runOnIdle { assertTrue(opened); assertTrue(bookmarked) }\n}')
    B(C, S, 2, 'sol', 'Finder thứ nhất trả về Row (cây merged); finder thứ hai trả về IconButton vì nút không bị gộp vào Row. `runOnIdle` chờ UI rảnh trước khi kiểm biến.', 'The first finder returns the Row (merged tree); the second returns the IconButton because the button is not merged into the Row. `runOnIdle` waits for the UI to be idle before checking the variables.')
    B(C, S, 3, 'ex', 'Một animation mở rộng thẻ dài 300 ms. Viết đoạn test chụp trạng thái ở giữa animation.', 'A card-expansion animation lasts 300 ms. Write a test snippet that captures the mid-animation state.')
    B(C, S, 3, 'hint', 'Tắt tự đẩy đồng hồ trước khi bấm.', 'Turn off automatic clock advancing before clicking.')
    B(C, S, 3, 'solkt', 'rule.mainClock.autoAdvance = false\nrule.onNodeWithText("Expand").performClick()\nrule.mainClock.advanceTimeBy(150)\nrule.onNodeWithTag("card").captureToImage()   // ảnh giữa animation\nrule.mainClock.autoAdvance = true')
    B(C, S, 3, 'sol', 'Đúng trường hợp tài liệu nêu cho `autoAdvance = false`: chụp animation ở thời điểm UI còn bận.', 'Exactly the case the docs give for `autoAdvance = false`: capturing an animation while the UI is still busy.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Cây nào cho trợ năng, cây nào cho test (mặc định)?', 'Which tree for accessibility, which for tests (by default)?')
    B(C, S, 1, 'ans', 'Trợ năng đọc cây unmerged và tự gộp; test dùng cây merged trừ khi `useUnmergedTree = true`.', 'Accessibility reads the unmerged tree and merges itself; tests use the merged tree unless `useUnmergedTree = true`.')
    B(C, S, 2, 'ask', 'Khi nào một con KHÔNG bị gộp vào cha đang gộp?', 'When is a child NOT merged into a merging parent?')
    B(C, S, 2, 'ans', 'Khi chính con cũng gộp (mergeDescendants = true, hoặc là nút/clickable).', 'When the child merges too (mergeDescendants = true, or it is a button/clickable).')
    B(C, S, 3, 'ask', 'Vì sao đổi state trong test mà UI chưa đổi?', 'Why does changing state in a test not update the UI yet?')
    B(C, S, 3, 'ans', 'Đồng hồ ảo chỉ được đẩy khi có action/assertion đồng bộ hoặc waitForIdle.', 'The virtual clock only advances on a synchronising action/assertion or waitForIdle.')
    for q, qv, qe, av, ae, wv, we in [
        ('q3', '`clearAndSetSemantics { }` (lambda rỗng) ảnh hưởng ai?', 'Who is affected by `clearAndSetSemantics { }` (empty lambda)?',
         'Mọi bên dùng: trợ năng, autofill, test.', 'Every consumer: accessibility, autofill, tests.', 'Muốn chỉ ẩn khỏi trợ năng thì dùng hideFromAccessibility.', 'To hide only from accessibility, use hideFromAccessibility.'),
        ('q4', 'Vùng chạm tối thiểu Tutorials dùng là bao nhiêu?', 'What minimum touch target does Tutorials use?',
         '48dp.', '48dp, per Material.', 'Icon 24dp cần padding hoặc IconButton.', 'A 24dp icon needs padding or an IconButton.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)

def override(o):
    C = 'b9'
    o(C + '.title', 'Semantics, accessibility và kiểm thử UI', 'Semantics, accessibility and UI testing')
    o(C + '.essence',
      'Song song với Composition là cây semantics: chỉ chứa ý nghĩa của UI (text, contentDescription, role, trạng thái, hành động), không chứa cách vẽ. Hai bên đọc nó: dịch vụ trợ năng như TalkBack (đọc cây unmerged và tự gộp) và framework kiểm thử (mặc định đọc cây merged). Component có sẵn tự điền semantics; composable tự vẽ phải tự khai báo.\n'
      'Gộp (`mergeDescendants`, có sẵn trong `clickable`, `Button`) quyết định độ chia mà người dùng TalkBack trải qua; con tự gộp thì đứng riêng. `clearAndSetSemantics` và `hideFromAccessibility` xóa hoặc ẩn, mỗi cái ảnh hưởng một nhóm người dùng khác nhau.\n'
      'Test UI tìm phần tử qua chính cây này (finder, action, assertion) và chạy trên đồng hồ ảo: hiểu đồng bộ là hiểu vì sao test đôi khi "thấy" UI cũ.',
      'Parallel to the Composition is the semantics tree: it holds only the UI\'s meaning (text, contentDescription, role, state, actions), not how to draw it. Two consumers read it: accessibility services such as TalkBack (reading the unmerged tree and merging themselves) and the testing framework (reading the merged tree by default). Built-in components fill in semantics; hand-drawn composables must declare their own.\n'
      'Merging (`mergeDescendants`, built into `clickable` and `Button`) decides the granularity TalkBack users experience; a self-merging child stays apart. `clearAndSetSemantics` and `hideFromAccessibility` erase or hide, each affecting a different set of consumers.\n'
      'UI tests find elements through this same tree (finders, actions, assertions) and run on a virtual clock: understanding synchronisation explains why a test sometimes "sees" the old UI.')
    o(C + '.goal.g1', 'Đã thấy cây semantics được dựng', 'Saw the semantics tree being built')
    o(C + '.goal.g2', 'Đã chạy một kịch bản tới cuối', 'Ran one scenario to the end')
